private fun isDone(c:Context,k:String)=c.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE).getBoolean(k,false)
private fun save(c:Context,k:String,v:Boolean=true)=c.getSharedPreferences("pathpilot_progress",Context.MODE_PRIVATE).edit().putBoolean(k,v).apply()

@Composable fun PathPilotFullApp(viewModel:PathPilotViewModel){
 var tab by remember{mutableStateOf("home")};var course by remember{mutableStateOf<Course?>(null)};var lesson by remember{mutableStateOf<LessonData?>(null)};var project by remember{mutableStateOf<Project?>(null)};var screen by remember{mutableStateOf<String?>(null)}
 BackHandler(course!=null||lesson!=null||project!=null||screen!=null){when{lesson!=null->lesson=null;course!=null->course=null;project!=null->project=null;else->screen=null}}
 Surface(Modifier.fillMaxSize(),color=Bg){when{lesson!=null->LessonPage(course!!.title,lesson!!){lesson=null};course!=null->CoursePage(course!!,{lesson=it}){course=null};project!=null->ProjectPage(project!!){project=null};screen=="git"->GitLab{screen=null};screen=="mentor"->Mentor{screen=null};else->Shell(tab,{tab=it},{course=it},{project=it},{screen="git"},{screen="mentor"})}}
}
