=""}},Modifier.weight(1f)){Text("Next")}}};item{Info("SHIP IT","After implementation: run tests → git diff → commit → push → PR → review → deploy → postmortem.",Orange)}}}
private fun projectHelp(t:String)=when{t.contains("Database",true)->"Define tables, keys and constraints before wiring UI.";t.contains("API",true)->"Define endpoint contract, validation, status codes and errors.";t.contains("Authentication",true)->"Enforce identity and resource ownership on every protected request.";t.contains("Tests",true)->"Cover the happy path and an important failure path.";t.contains("Deployment",true)->"Document environment variables, health check and rollback.";t.contains("Security",true)->"Threat-model the feature and document a mitigation.";else->"Produce a concrete artifact: code, command output, design decision, test result or client-ready document."}

@Composable private fun GitLab(back:()->Unit){val ctx=LocalContext.current;var step by remember{mutableIntStateOf(0)};var input by remember{mutableStateOf("")};var terminal by remember{mutableStateOf("$ pathpilot@lab:~/expense-manager\nReady for git status")};val expected=gitSteps[step];LazyColumn(contentPadding=PaddingValues(bottom=30.dp),verticalArrangement=Arrangement.spacedBy(11.dp)){item{Back("Git + GitHub Lab","Interactive terminal practice",back)};item{Hero("Mission ${step+1}/${gitSteps.size}",gitHint(expected),Icons.Default.Terminal)};item{Card(Modifier.padding(horizontal=16.dp).fillMaxWidth(),colors=CardDefaults.cardColors(Color(0xFF0B1220)),shape=RoundedCornerShape(19.dp)){Column(Modifier.padding(15.dp)){Text(terminal,color=Color(0xFFE5E7EB),fontFamily=FontFamily.Monospace,fontSize=11.sp);OutlinedTextField(input,{input=it},Modifier.fillMaxWidth().padding(top=10.dp),label={Text("Type command / action")},singleLine=true,textStyle=LocalTextStyle.current.copy(fontFamily=FontFamily.Monospace),colors=OutlinedTextFieldDefaults.colors(focusedTextColor=Color.White,unfocusedTextColor=Color.White,focusedBorderColor=Cyan,unfocusedBorderColor=Color(0xFF475569),focusedLabelColor=Cyan,unfocusedLabelColor=Color(0xFF94A3B8));Button({val ok=if(expected.startsWith("open")||expected.startsWith("review")||expected.startsWith("merge"))input.trim().isNotEmpty()else input.trim().equals(expected,true);if(ok){save(ctx,"git:$expected");terminal="$ pathpilot@lab $input\n✓ accepted\n${gitHint(expected)}";input="";if(step<gitSteps.lastIndex)step++else terminal+="\n\n🎉 Complete: ticket → branch → commit → PR → review → merge."}else terminal="$ pathpilot@lab $input\n✗ Not accepted\nHint: $expected"},Modifier.fillMaxWidth().padding(top=9.dp)){Icon(Icons.Default.PlayArrow,null);Spacer(Modifier.width(5.dp));Text("Run command")}}}};item{Section("Workflow")};itemsIndexed(gitSteps){i,s->val d=isDone(ctx,"git:$s");Row(Modifier.padding(horizontal=20.dp,vertical=4.dp),verticalAlignment=Alignment.CenterVertically){Icon(if(d||i<step)Icons.Default.CheckCircle else if(i==step)Icons.Default.PlayCircle else Icons.Default.RadioButtonUnchecked,null,tint=if(d||i<step)Green else if(i==step)Blue else Muted);Spacer(Modifier.width(8.dp));Text(s,fontSize=11.sp,color=if(i==step)Navy else Muted,fontWeight=if(i==step)FontWeight.Bold else FontWeight.Normal)}};item{Info("REAL GITHUB","This is honest in-app Git practice. It does not fake a real GitHub commit or PR. Real GitHub push/PR integration needs explicit GitHub authorization and can be added separately.",Orange)}}}
private fun gitHint(s:String)=when{s=="git status"->"Inspect your working tree before changing anything.";s.startsWith("git switch")->"Create a feature branch instead of editing main.";s=="git diff"->"Review exactly what changed.";s=="git add ."->"Stage the intended files.";s.startsWith("git commit")->"Create one focused, reviewable commit.";s.startsWith("git log")->"Inspect history.";s.startsWith("git push")->"Push the feature branch.";s.startsWith("open")->"Create a PR with summary, tests and evidence.";s.startsWith("review")->"Read CI/reviewer feedback, fix and push again.";else->"Merge only after required checks pass."}

